import { Component, ComponentInterface, Event, EventEmitter, h, Host } from '@stencil/core';

@Component({
  tag: 'groupui-global-top-navigation-utility-items',
  styleUrl: 'global-top-navigation-utility-items.scss',
  shadow: true,
})
export class GlobalTopNavigationUtilityItems implements ComponentInterface {
  /**
   * @internal
   */
  @Event() groupuiSlotchange: EventEmitter<void>;

  private handleSlotChange = (): void => {
    this.groupuiSlotchange.emit();
  };

  render() {
    return (
      <Host slot="utility-items">
        <div role="list">
          <slot onSlotchange={this.handleSlotChange}></slot>
        </div>
      </Host>
    );
  }
}
